        {"-format",          NULL,        "format SQL from stdin, writing result to stdout"},
        {"-format-file",     "FILENAME",  "format SQL in file, writing result to stdout"},
        {"-init",            "FILENAME",  "read/process named file"},
        {"-header",          NULL,        "turn headers on"},
        {"-h",               NULL,        "show help message"},
        {"-help",            NULL,        "show help message"},
        {"-html",            NULL,        "set output mode to HTML"},
        {"-interactive",     NULL,        "force interactive I/O"},
        {"-json",            NULL,        "set output mode to 'json'"},
        {"-jsonlines",       NULL,        "set output mode to 'jsonlines'"},
        {"-line",            NULL,        "set output mode to 'line'"},
        {"-list",            NULL,        "set output mode to 'list'"},
        {"-markdown",        NULL,        "set output mode to 'markdown'"},
        {"-newline",         "SEP",       "set output row separator. Default: '\\n'"},
        {"-no-init",         NULL,        "skip processing the init file"},
        {"-no-stdin",        NULL,        "exit after processing options instead of reading stdin"},
        {"-noheader",        NULL,        "turn headers off"},
        {"-nullvalue",       "TEXT",      "set text string for NULL values. Default 'NULL'"},
        {"-quote",           NULL,        "set output mode to 'quote'"},
        {"-readonly",        NULL,        "open the database read-only"},
        {"-s",               "COMMAND",   "run \"COMMAND\" and exit"},
        {"-safe",            NULL,        "enable safe-mode"},
        {"-separator",       "SEP",       "set output column separator. Default: '|'"},
        {"-storage-version", "VER",       "database storage compatibility version to use. Default: 'v0.10.0'"},
        {"-table",           NULL,        "set output mode to 'table'"},
        {"-ui",              NULL,        "launches a web interface using the ui extension (configurable with .ui_command)"},
        {"-unredacted",      NULL,        "allow printing unredacted secrets"},
        {"-unsigned",        NULL,        "allow loading of unsigned extensions"},
        {"-version",         NULL,        "show DuckDB version"},
    };
    const size_t n = sizeof(opts) / sizeof(opts[0]);
    for (size_t i = 0; i < n; i++) {
        /* The total "rendered" (non-escape) width of name + " " + arg is padded to 23,
         * then the description follows. */
        int rendered = (int)strlen(opts[i].name);
        if (opts[i].arg) {
            rendered += 1 + (int)strlen(opts[i].arg);
        }
        int pad = 23 - rendered;
        if (pad < 1) pad = 1;
        if (opts[i].arg) {
            printf("\x1b[00m\x1b[32m  %s\x1b[00m\x1b[33m %s\x1b[00m%*s%s\n",
                   opts[i].name, opts[i].arg, pad, "", opts[i].desc);
        } else {
