static bool is_known_option(const char *opt) {
    for (size_t i = 0; i < NUM_KNOWN; i++) {
        if (strcmp(KNOWN_OPTIONS[i], opt) == 0) return true;
    }
    return false;
}

/* Simple Levenshtein distance */
static int lev(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    int *prev = calloc(lb + 1, sizeof(int));
    int *cur  = calloc(lb + 1, sizeof(int));
    for (size_t j = 0; j <= lb; j++) prev[j] = (int)j;
    for (size_t i = 1; i <= la; i++) {
        cur[0] = (int)i;
        for (size_t j = 1; j <= lb; j++) {
            int cost = (a[i-1] == b[j-1]) ? 0 : 1;
            int del = prev[j] + 1;
            int ins = cur[j-1] + 1;
            int sub = prev[j-1] + cost;
            int m = del < ins ? del : ins;
            if (sub < m) m = sub;
            cur[j] = m;
        }
        int *t = prev; prev = cur; cur = t;
    }
    int r = prev[lb];
    free(prev); free(cur);
    return r;
}

static void print_unknown_option(const char *argv0, const char *opt) {
    fprintf(stderr, "Unknown Option Error: Unrecognized option '%s'\n\n", opt);
    /* Find up to 5 closest by Levenshtein distance */
    int dists[128];
    int order[128];
    for (size_t i = 0; i < NUM_KNOWN; i++) {
        dists[i] = lev(opt, KNOWN_OPTIONS[i]);
        order[i] = (int)i;
    }
    /* stable sort by distance asc, then original index */
    for (size_t i = 1; i < NUM_KNOWN; i++) {
        for (size_t j = i; j > 0 && dists[order[j]] < dists[order[j-1]]; j--) {
            int t = order[j]; order[j] = order[j-1]; order[j-1] = t;
        }
    }
    int k = NUM_KNOWN < 5 ? (int)NUM_KNOWN : 5;
    fprintf(stderr, "Did you mean: ");
    for (int i = 0; i < k; i++) {
        if (i > 0) fprintf(stderr, ", ");
        fprintf(stderr, "\"%s\"", KNOWN_OPTIONS[order[i]]);
    }
    fprintf(stderr, "\nRun '%s -help' for a list of options.\n\n", argv0);
}

int main(int argc, char **argv) {
    const char *argv0 = argv[0];
    if (argc >= 2) {
        const char *a = argv[1];
        if (strcmp(a, "-version") == 0 || strcmp(a, "--version") == 0) {
            printf("%s\n", VERSION_STRING);
            return 0;
        }
        if (strcmp(a, "-h") == 0 || strcmp(a, "-help") == 0 || strcmp(a, "--help") == 0) {
            print_help(argv0);
            return 0;
        }
        if (a[0] == '-' && !is_known_option(a)) {
            print_unknown_option(argv0, a);
            return 1;
        }
    }
    /* Unsupported path: for anything else, exit silently with 0 (matches behavior for
     * options that would open a REPL / read stdin, which we cannot faithfully recreate). */
    return 0;
}
