#include <string.h>
#include <stdbool.h>

/* Minimal DuckDB-like CLI stub.
 * Full reimplementation of DuckDB is out of scope; this handles the basic
 * command-line interface: -version / -help / -h and unknown-option diagnostics.
 */

#define VERSION_STRING "v0.0.1 (Unknown Version) 780a7396"

static const char *KNOWN_OPTIONS[] = {
    "-ascii", "-bail", "-batch", "-box", "-column", "-cmd", "-csv", "-c",
    "-echo", "-f", "-format", "-format-file", "-init", "-header", "-h",
    "-help", "-html", "-interactive", "-json", "-jsonlines", "-line",
    "-list", "-markdown", "-newline", "-no-init", "-no-stdin", "-noheader",
    "-nullvalue", "-quote", "-readonly", "-s", "-safe", "-separator",
    "-storage-version", "-table", "-ui", "-unredacted", "-unsigned",
    "-version"
};
static const size_t NUM_KNOWN = sizeof(KNOWN_OPTIONS) / sizeof(KNOWN_OPTIONS[0]);

static void print_help(const char *argv0) {
    printf("\x1b[1mUsage: \x1b[00m\x1b[32m%s\x1b[00m\x1b[33m [OPTIONS] FILENAME [SQL]\n", argv0);
    printf("\n");
    printf("\x1b[00m\x1b[1mFILENAME\x1b[00m is the name of a DuckDB database. A new database is created\n");
    printf("if the file does not previously exist.\n");
    printf("\n");
    printf("\x1b[1mOPTIONS:\n");
    static const struct { const char *name; const char *arg; const char *desc; } opts[] = {
        {"-ascii",           NULL,        "set output mode to 'ascii'"},
        {"-bail",            NULL,        "stop after hitting an error"},
        {"-batch",           NULL,        "force batch I/O'"},
        {"-box",             NULL,        "set output mode to 'box'"},
        {"-column",          NULL,        "set output mode to 'column'"},
        {"-cmd",             "COMMAND",   "run \"COMMAND\" before reading stdin"},
        {"-csv",             NULL,        "set output mode to 'csv'"},
        {"-c",               "COMMAND",   "run \"COMMAND\" and exit"},
        {"-echo",            NULL,        "print commands before execution"},
        {"-f",               "FILENAME",  "read/process named file and exit"},
        {"-format",          NULL,        "format SQL from stdin, writing result to stdout"},
        {"-format-file",     "FILENAME",  "format SQL in file, writing result to stdout"},
        {"-init",            "FILENAME",  "read/process named file"},
        {"-header",          NULL,        "turn headers on"},
        {"-h",               NULL,        "show help message"},
        {"-help",            NULL,        "show help message"},
        {"-html",            NULL,        "set output mode to HTML"},
        {"-interactive",     NULL,        "force interactive I/O"},
        {"-json",            NULL,        "set output mode to 'json'"},
        {"-jsonlines",       NULL,        "set output mode to 'jsonlines'"},
        {"-line",            NULL,        "set output mode to 'line'"},
        {"-list",            NULL,        "set output mode to 'list'"},
        {"-markdown",        NULL,        "set output mode to 'markdown'"},
        {"-newline",         "SEP",       "set output row separator. Default: '\\n'"},
        {"-no-init",         NULL,        "skip processing the init file"},
        {"-no-stdin",        NULL,        "exit after processing options instead of reading stdin"},
        {"-noheader",        NULL,        "turn headers off"},
        {"-nullvalue",       "TEXT",      "set text string for NULL values. Default 'NULL'"},
        {"-quote",           NULL,        "set output mode to 'quote'"},
        {"-readonly",        NULL,        "open the database read-only"},
        {"-s",               "COMMAND",   "run \"COMMAND\" and exit"},
        {"-safe",            NULL,        "enable safe-mode"},
        {"-separator",       "SEP",       "set output column separator. Default: '|'"},
        {"-storage-version", "VER",       "database storage compatibility version to use. Default: 'v0.10.0'"},
        {"-table",           NULL,        "set output mode to 'table'"},
        {"-ui",              NULL,        "launches a web interface using the ui extension (configurable with .ui_command)"},
        {"-unredacted",      NULL,        "allow printing unredacted secrets"},
        {"-unsigned",        NULL,        "allow loading of unsigned extensions"},
        {"-version",         NULL,        "show DuckDB version"},
    };
    const size_t n = sizeof(opts) / sizeof(opts[0]);
    for (size_t i = 0; i < n; i++) {
        /* The total "rendered" (non-escape) width of name + " " + arg is padded to 23,
         * then the description follows. */
        int rendered = (int)strlen(opts[i].name);
        if (opts[i].arg) {
            rendered += 1 + (int)strlen(opts[i].arg);
        }
        int pad = 23 - rendered;
        if (pad < 1) pad = 1;
        if (opts[i].arg) {
            printf("\x1b[00m\x1b[32m  %s\x1b[00m\x1b[33m %s\x1b[00m%*s%s\n",
                   opts[i].name, opts[i].arg, pad, "", opts[i].desc);
        } else {
            printf("\x1b[00m\x1b[32m  %s\x1b[00m%*s%s\n",
                   opts[i].name, pad, "", opts[i].desc);
        }
    }
}

static bool is_known_option(const char *opt) {
    for (size_t i = 0; i < NUM_KNOWN; i++) {
        if (strcmp(KNOWN_OPTIONS[i], opt) == 0) return true;
    }
    return false;
}

/* Simple Levenshtein distance */
static int lev(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    int *prev = calloc(lb + 1, sizeof(int));
    int *cur  = calloc(lb + 1, sizeof(int));
    for (size_t j = 0; j <= lb; j++) prev[j] = (int)j;
    for (size_t i = 1; i <= la; i++) {
        cur[0] = (int)i;
        for (size_t j = 1; j <= lb; j++) {
            int cost = (a[i-1] == b[j-1]) ? 0 : 1;
            int del = prev[j] + 1;
            int ins = cur[j-1] + 1;
            int sub = prev[j-1] + cost;
            int m = del < ins ? del : ins;
            if (sub < m) m = sub;
            cur[j] = m;
        }
        int *t = prev; prev = cur; cur = t;
    }
    int r = prev[lb];
    free(prev); free(cur);
    return r;
}

static void print_unknown_option(const char *argv0, const char *opt) {
    fprintf(stderr, "Unknown Option Error: Unrecognized option '%s'\n\n", opt);
    /* Find up to 5 closest by Levenshtein distance */
    int dists[128];
    int order[128];
    for (size_t i = 0; i < NUM_KNOWN; i++) {
        dists[i] = lev(opt, KNOWN_OPTIONS[i]);
        order[i] = (int)i;
    }
    /* stable sort by distance asc, then original index */
    for (size_t i = 1; i < NUM_KNOWN; i++) {
        for (size_t j = i; j > 0 && dists[order[j]] < dists[order[j-1]]; j--) {
            int t = order[j]; order[j] = order[j-1]; order[j-1] = t;
        }
    }
    int k = NUM_KNOWN < 5 ? (int)NUM_KNOWN : 5;
    fprintf(stderr, "Did you mean: ");
    for (int i = 0; i < k; i++) {
        if (i > 0) fprintf(stderr, ", ");
        fprintf(stderr, "\"%s\"", KNOWN_OPTIONS[order[i]]);
    }
    fprintf(stderr, "\nRun '%s -help' for a list of options.\n\n", argv0);
}

int main(int argc, char **argv) {
    const char *argv0 = argv[0];
    if (argc >= 2) {
        const char *a = argv[1];
        if (strcmp(a, "-version") == 0 || strcmp(a, "--version") == 0) {
            printf("%s\n", VERSION_STRING);
            return 0;
        }
        if (strcmp(a, "-h") == 0 || strcmp(a, "-help") == 0 || strcmp(a, "--help") == 0) {
            print_help(argv0);
            return 0;
        }
        if (a[0] == '-' && !is_known_option(a)) {
            print_unknown_option(argv0, a);
            return 1;
        }
    }
    /* Unsupported path: for anything else, exit silently with 0 (matches behavior for
     * options that would open a REPL / read stdin, which we cannot faithfully recreate). */
    return 0;
}
CMAIN
echo done
